<script setup>import {ref,computed} from 'vue';import {useRouter} from 'vue-router';import {api} from '../services/api';import {store} from '../main';const router=useRouter();const form=ref({name:'',email:'',address:'',city:'',country:'',payment:'card'});const total=computed(()=>store.cart.reduce((s,i)=>s+i.price*i.quantity,0));const submitting=ref(false);async function submit(){if(!form.value.name||!form.value.email||!form.value.address)return alert('Please complete your shipping details.');submitting.value=true;try{const r=await api.order({customer:form.value,items:store.cart.map(i=>({productId:i.productId,quantity:i.quantity})),shipping:0});localStorage.removeItem('vora-cart');store.cart.splice(0);router.push(`/order-confirmed/${r.data.id}`)}catch(e){alert(e.message)}finally{submitting.value=false}}</script>
<template><section class="simple-page"><div class="steps">Cart → <b>Shipping</b> → Payment → Review</div><div class="checkout-layout"><div><h1>Secure Checkout</h1><p>Your payment information is encrypted and securely processed.</p><div class="form-grid"><label>Full Name<input v-model="form.name"></label><label>Email<input v-model="form.email" type="email"></label><label class="wide">Shipping Address<input v-model="form.address"></label><label>City<input v-model="form.city"></label><label>Country<input v-model="form.country"></label><label class="wide">Payment Method<select v-model="form.payment"><option value="card">Credit / Debit Card</option><option value="wallet">Digital Wallet</option></select></label></div><button class="btn primary" :disabled="submitting||!store.cart.length" @click="submit">{{submitting?'Processing…':'Place Order'}}</button></div><aside class="summary"><span>Order Summary</span><div v-for="i in store.cart" class="line"><span>{{i.name}} × {{i.quantity}}</span><b>${{(i.price*i.quantity).toFixed(2)}}</b></div><hr><h2>${{total.toFixed(2)}}</h2></aside></div></section></template>
